def advancePermutation(perm, k):
    n = len(perm)
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i
    rank = 0
    for i in range(n):
        smaller = 0
        for j in range(i + 1, n):
            if perm[j] < perm[i]:
                smaller += 1
        rank += smaller * fact[n - 1 - i]
    rank = (rank + k) % fact[n]
    pool = list(range(1, n + 1))
    res = []
    for i in range(n):
        idx, rank = divmod(rank, fact[n - 1 - i])
        res.append(pool.pop(idx))
    return res
